def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    sources = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c]]

    rays = []
    for r, c, color in sources:
        if color == 1:
            rays.append([(r, c + 1), (r, c + 2), (r - 1, c + 2)])
        elif color == 2:
            rays.append([(r, c - i) for i in range(1, 5)])
        elif color == 3:
            rays.append([(r + i, c) for i in range(1, 4)])
        elif color == 6:
            rays.append([(r - i, c) for i in range(1, 7)])

    # Draw the rays, with their final cell in the source color.
    for (r, c, color), ray in zip(sources, rays):
        for rr, cc in ray:
            if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == 0:
                out[rr][cc] = 5
        if ray:
            rr, cc = ray[-1]
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color

    # Where rays cross, mark the crossing as 4 and continue diagonally down-left.
    crossings = set()
    for i in range(len(rays)):
        for j in range(i + 1, len(rays)):
            a = set(rays[i])
            b = set(rays[j])
            crossings.update(a & b)

    for r, c in crossings:
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = 4
            k = 1
            while r + k < h and c - k >= 0:
                out[r + k][c - k] = 4
                k += 1

    # Keep the original objects intact.
    for r, c, color in sources:
        out[r][c] = color
    return out
